"use strict";function formatCookie(arr,url){return arr[0]+"="+arr[1]+"; Path="+arr[3]+"; Domain="+url+".com"}function normalizeCookieHeaderString(cookieString){let str=String(cookieString||"").trim();if(!str)return[];if(/^cookie\s*:/i.test(str)){str=str.replace(/^cookie\s*:/i,"").trim()}str=str.replace(/\r?\n/g," ").replace(/\s*;\s*/g,";");const parts=str.split(";").map(v=>v.trim()).filter(Boolean);const output=[];for(const part of parts){const eqIndex=part.indexOf("=");if(eqIndex<=0)continue;const key=part.slice(0,eqIndex).trim();const value=part.slice(eqIndex+1).trim().replace(/^"(.*)"$/,"$1");if(!key)continue;output.push(`${key}=${value}`)}return output}function setJarFromPairs(jar,cookiePairs,domain=".facebook.com"){const cookieDomain=String(domain||".facebook.com").replace(/^\./,"");const url=cookieDomain==="facebook.com"?"https://www.facebook.com/":`https://${cookieDomain}/`;for(const cookiePair of cookiePairs||[]){if(!cookiePair||typeof cookiePair!=="string"||!cookiePair.includes("="))continue;try{const cookieString=`${cookiePair}; Domain=${cookieDomain}; Path=/`;if(typeof jar.setCookieSync==="function"){jar.setCookieSync(cookieString,url)}else if(typeof jar.setCookie==="function"){jar.setCookie(cookieString,url)}}catch(err){}}}function setJarFromCookies(jar,cookies,defaultUrl="https://www.facebook.com/"){for(const cookie of cookies||[]){if(!cookie||typeof cookie!=="object")continue;const name=cookie.name||cookie.key;if(!name||cookie.value===undefined||cookie.value===null)continue;const domain=cookie.domain?String(cookie.domain).replace(/^\./,""):null;const url=domain?`https://${domain}/`:defaultUrl;const attributes=[cookie.path?`Path=${cookie.path}`:"Path=/",domain?`Domain=${domain}`:"",cookie.expires&&cookie.expires!==-1?`Expires=${new Date(cookie.expires).toUTCString()}`:"",cookie.expirationDate&&Number.isFinite(Number(cookie.expirationDate))?`Expires=${new Date(Number(cookie.expirationDate)*1e3).toUTCString()}`:"",cookie.secure?"Secure":"",cookie.httpOnly?"HttpOnly":"",cookie.sameSite?`SameSite=${cookie.sameSite}`:""].filter(Boolean);try{jar.setCookieSync(`${name}=${cookie.value}; ${attributes.join("; ")}`,url)}catch(_){}}}function formatCookieWithDomain(arr,service="facebook"){const name=String(arr?.[0]||"");const value=String(arr?.[1]||"");return`${name}=${value}; Domain=.${service}.com; Path=/; Secure`}module.exports=formatCookie;module.exports.formatCookie=formatCookie;module.exports.normalizeCookieHeaderString=normalizeCookieHeaderString;module.exports.setJarFromPairs=setJarFromPairs;module.exports.setJarFromCookies=setJarFromCookies;module.exports.formatCookieWithDomain=formatCookieWithDomain;
